import base64,hashlib,json,os,secrets,subprocess,sys,time
from pathlib import Path
ROOT=Path.cwd(); CHAT=-1002373696859; TOPIC=1; OLD=4703
LEDGER=ROOT/"deploy/state/startless-recover-missing-topic1-20261122.json"
def run(argv,input=None,timeout=120):
 return subprocess.run(argv,input=input,capture_output=True,text=True,timeout=timeout)
def db(sql):
 p=run(["docker","exec","deploy-postgres-1","psql","-X","-q","-v","ON_ERROR_STOP=1","-U","gace","-d","gaybbs","-At","-F","|","-c",sql],timeout=30)
 if p.returncode:raise RuntimeError("DATABASE_COMMAND_FAILED")
 return [x.strip() for x in p.stdout.splitlines() if x.strip()]
def audit():
 p=run(["python3","scripts/userbot_topic_audit_client.py","--chat-id",str(CHAT),"--topic-id",str(TOPIC)],timeout=125)
 if p.returncode:raise RuntimeError("RESIDENT_AUDIT_FAILED")
 docs=[json.loads(x.split("=",1)[1]) for x in p.stdout.splitlines() if x.startswith("USERBOT_TOPIC_AUDIT=")]
 if len(docs)!=1 or len(docs[0].get("rows",[]))!=1:raise RuntimeError("AUDIT_SHAPE_INVALID")
 return docs[0]["rows"][0]
def persist(value,first=False):
 tmp=LEDGER.with_suffix(".next")
 if first:
  fd=os.open(LEDGER,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
 else:
  fd=os.open(tmp,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
 with os.fdopen(fd,"w") as f:
  json.dump(value,f,ensure_ascii=False,sort_keys=True);f.flush();os.fsync(f.fileno())
 if not first:os.replace(tmp,LEDGER)
def fail(code):
 print("TOPIC1_RECOVERY_STATE="+code)
 raise SystemExit(1)
if LEDGER.exists() or LEDGER.is_symlink():fail("PRIOR_ATTEMPT_PROTECTED")
if run(["systemctl","--user","is-active","gace-userbot-verify.service"]).stdout.strip()!="active":fail("USERBOT_INACTIVE")
if run(["docker","inspect","-f","{{.State.Running}}","deploy-gaybbs-1"]).stdout.strip()!="true":fail("BOT_INACTIVE")
rows=db(f"SELECT message_id,state,pinned FROM topic_dm_entry_pins WHERE chat_id={CHAT} AND message_thread_id={TOPIC}")
