if db(f"SELECT count(*) FROM posting_topics WHERE chat_id={CHAT} AND message_thread_id={TOPIC} AND purpose='link'")!=["0"]:fail("LINK_TOPIC_EXCLUDED")
if db(f"SELECT count(*) FROM board_menu_panels WHERE chat_id={CHAT} AND message_thread_id={TOPIC} AND panel_type='general_guide'")!=["0"]:fail("GENERAL_GUIDE_EXCLUDED")
a=audit()
if "お知らせ" not in str(a.get("title","")) or a.get("post_button")!="ABSENT" or a.get("pin_state")!="ABSENT_FROM_PINS" or a.get("history_inspected",0)<1 or (a.get("migration") or {})!={"message_id":OLD,"transport":"NOT_FOUND"}:fail("ORIGINAL_MESSAGE_OR_BUTTON_PRESENT")
token=base64.urlsafe_b64encode(secrets.token_bytes(24)).decode().rstrip("=")
digest=hashlib.sha256(("GayBBS-menu-v1:"+token).encode()).hexdigest()
persist({"state":"ATTEMPTING","chat_id":CHAT,"topic_id":TOPIC,"missing_original_id":OLD},first=True)
changed=db(f"UPDATE topic_dm_entry_pins SET state='publishing',pinned=FALSE,updated_at=NOW() WHERE chat_id={CHAT} AND message_thread_id={TOPIC} AND message_id={OLD} AND state='published' AND pinned=TRUE RETURNING message_id")
if changed!=[str(OLD)]:
 persist({"state":"CLAIM_NOT_CONFIRMED","missing_original_id":OLD});fail("DATABASE_CLAIM_FAILED")
a=audit()
if "お知らせ" not in str(a.get("title","")) or a.get("post_button")!="ABSENT" or a.get("pin_state")!="ABSENT_FROM_PINS" or (a.get("migration") or {}).get("transport")!="NOT_FOUND":
 db(f"UPDATE topic_dm_entry_pins SET state='published',pinned=TRUE WHERE chat_id={CHAT} AND message_thread_id={TOPIC} AND message_id={OLD} AND state='publishing'")
 persist({"state":"CANCELLED_BEFORE_SEND","missing_original_id":OLD});fail("CONCURRENT_LIVE_MESSAGE")
node=r"""
'use strict';
const fs=require('node:fs');const https=require('node:https');
const t=__TASK_JSON__;
const token=fs.readFileSync(process.env.BOT_TOKEN_FILE||'/run/secrets/bot_token','utf8').trim();
const agent=new https.Agent({family:4,keepAlive:false,timeout:20000});
function api(m,data){return new Promise((resolve,reject)=>{
 const body=JSON.stringify(data);
 const req=https.request({hostname:'api.telegram.org',path:'/bot'+token+'/'+m,method:'POST',agent,timeout:25000,
 headers:{'content-type':'application/json','content-length':Buffer.byteLength(body)}},res=>{
 let s='';res.on('data',x=>{if(s.length<16000)s+=x});res.on('end',()=>{try{const x=JSON.parse(s);resolve(x.ok?{ok:true,value:x.result}:{ok:false,code:x.error_code})}catch{reject(Error('RESPONSE_INVALID'))}})});
 req.on('error',()=>reject(Error('TRANSPORT_UNKNOWN')));req.on('timeout',()=>req.destroy(Error('TIMEOUT_UNKNOWN')));req.end(body);
})}
(async()=>{
 const me=await api('getMe',{});if(!me.ok||me.value.username?.toLowerCase()!=='gaybbs_bot'||me.value.id===8086265383)throw Error('BOT_IDENTITY_INVALID');
 const sent=await api('sendMessage',{chat_id:t.chat,message_thread_id:t.topic,disable_notification:true,
  text:'📝 このトピックへの投稿はこちら\n下のボタンからBotの投稿メニューを開いてください。',
  reply_markup:{inline_keyboard:[[{text:'📝 投稿メニューを開く',callback_data:t.callback}]]}});
 if(!sent.ok){console.log(JSON.stringify({state:'SEND_DENIED',code:sent.code}));process.exitCode=2;return}
 const v=sent.value;
 if(v.chat?.id!==t.chat||!Number.isInteger(v.message_id)||v.message_id<=0||(v.message_thread_id!==t.topic && !(t.topic===1 && v.message_thread_id==null)))throw Error('SEND_ACK_UNCERTAIN');
 const pin=await api('pinChatMessage',{chat_id:t.chat,message_id:v.message_id,disable_notification:true});
 console.log(JSON.stringify({state:pin.ok?'PUBLISHED_PINNED':'PUBLISHED_PIN_UNCERTAIN',message_id:v.message_id}));
 if(!pin.ok)process.exitCode=3;
})().catch(e=>{console.log(JSON.stringify({state:'UNCERTAIN',error:String(e?.message||'UNKNOWN').replace(/[^A-Z_]/g,'').slice(0,50)}));process.exitCode=4});
"""
p=run(["docker","exec","-i","deploy-gaybbs-1","node","-"],input=node.replace("__TASK_JSON__",json.dumps({"chat":CHAT,"topic":TOPIC,"callback":"gdm:p_"+token})),timeout=95)
try:
 d=[json.loads(x) for x in p.stdout.splitlines() if x.startswith("{")]
 result=d[0] if len(d)==1 else {"state":"UNKNOWN"}
except:result={"state":"UNKNOWN"}
mid=result.get("message_id")
if isinstance(mid,int) and mid>0 and result.get("state")!="PUBLISHED_PINNED":
 db(f"UPDATE topic_dm_entry_pins SET message_id={mid},token_hash='{digest}',state='needs_reconcile' WHERE chat_id={CHAT} AND message_thread_id={TOPIC} AND message_id={OLD} AND state='publishing'")
 persist({"state":"TELEGRAM_POST_PIN_UNCONFIRMED","missing_original_id":OLD,"message_id":mid});fail("PIN_UNCONFIRMED")
if p.returncode or result.get("state")!="PUBLISHED_PINNED" or not isinstance(mid,int):
 db(f"UPDATE topic_dm_entry_pins SET state='needs_reconcile' WHERE chat_id={CHAT} AND message_thread_id={TOPIC} AND message_id={OLD} AND state='publishing'")
 persist({"state":"TELEGRAM_SEND_UNCERTAIN","missing_original_id":OLD});fail("SEND_UNCERTAIN")
changed=db(f"UPDATE topic_dm_entry_pins SET message_id={mid},token_hash='{digest}',state='published',pinned=TRUE,updated_at=NOW() WHERE chat_id={CHAT} AND message_thread_id={TOPIC} AND message_id={OLD} AND state='publishing' RETURNING message_id")
if changed!=[str(mid)]:
 persist({"state":"POST_SENT_DB_UNCONFIRMED","missing_original_id":OLD,"message_id":mid});fail("DATABASE_FINALIZE_UNKNOWN")
persist({"state":"PUBLISHED_ACK_CONFIRMED","missing_original_id":OLD,"message_id":mid})
for i in range(3):
 a=audit()
 if a.get("post_button")=="PRESENT" and mid in a.get("pin_message_ids",[])+a.get("history_message_ids",[]):
  persist({"state":"VERIFIED","missing_original_id":OLD,"message_id":mid})
  print("TOPIC1_STARTLESS_NEW_POST=VERIFIED")
  break
 if i<2:time.sleep(2)
else:fail("PUBLISHED_AWAITING_USERBOT_READBACK")
if db(f"SELECT count(*) FROM topic_dm_entry_pins WHERE chat_id={CHAT} AND message_thread_id={TOPIC} AND message_id={mid} AND pinned=TRUE AND state='published' AND token_hash='{digest}'")!=["1"]:fail("PIN_LEDGER_READBACK_FAILED")
if run(["systemctl","--user","is-active","gace-userbot-verify.service"]).stdout.strip()!="active":fail("USERBOT_NOT_ACTIVE_AFTER")
print("ORIGINAL_MISSING_ID_PROTECTED=YES;NO_DELETION=YES")
PY
